from packaging.dependency_groups import resolve_dependency_groups as _resolve_dependency_groups


def resolve_dependency_groups(dependency_groups: dict[str, list[str | dict[str, str]]], groups: list[str]) -> list[str]:
    """Resolve dependency groups to a tuple of requirements as strings. dependency_groups: the parsed contents of the [dependency-groups] table from pyproject.toml; groups: the name of the group(s) to resolve, e.g. ['base', 'dev'] -> ['requests>=2.0.0', 'pytest>=6.0.0']."""
    try:
        return list(_resolve_dependency_groups(dependency_groups, *groups))
    except Exception as e:
        raise ValueError(f"Failed to resolve dependency groups: {str(e)}")

from packaging.licenses import canonicalize_license_expression, InvalidLicenseExpression


def canonicalize_license_expression(raw_license_expression: str) -> str:
    """Normalize a license expression to its canonical form. raw_license_expression: The License-Expression to canonicalize, e.g. 'mit and apache-2.0' -> 'MIT AND Apache-2.0'."""
    if not isinstance(raw_license_expression, str):
        raise ValueError("raw_license_expression must be a string")

    try:
        result = canonicalize_license_expression(raw_license_expression)
        return str(result)
    except InvalidLicenseExpression as e:
        raise ValueError(str(e)) from e

from packaging.metadata import parse_email


def parse_metadata_email(data: str) -> dict[str, dict[str, str | list[str] | dict[str, str]] | dict[str, list[str]]]:
    """Parse distribution metadata stored as email headers. data: Distribution metadata as email headers, e.g. 'Name: example\nVersion: 1.0\n' -> {'core': {'name': 'example', 'version': '1.0'}, 'unparsed': {}}."""
