from packaging.metadata import Metadata


def create_metadata_from_email(data: str, validate: bool = True) -> dict[str, str | list[str] | None]:
    """Parse metadata from email headers.

    Args:
        data: Email header data containing metadata
        validate: Whether to validate the parsed metadata

    Returns:
        Dictionary representation of the metadata

    Example:
        >>> create_metadata_from_email('Metadata-Version: 2.1\\nName: example-package\\nVersion: 1.0.0\\n', True)
        {'metadata_version': '2.1', 'name': 'example-package', 'version': '1.0.0'}
    """
    try:
        metadata = Metadata.from_email(data, validate=validate)
        # Convert metadata object to dictionary representation
        result = {}

        # Handle basic fields - convert to strings
        if hasattr(metadata, 'metadata_version'):
            result['metadata_version'] = str(metadata.metadata_version)
        if hasattr(metadata, 'name'):
            result['name'] = str(metadata.name) if metadata.name is not None else None
        if hasattr(metadata, 'version'):
            result['version'] = str(metadata.version) if metadata.version is not None else None
        if hasattr(metadata, 'summary'):
            result['summary'] = str(metadata.summary) if metadata.summary is not None else None
        if hasattr(metadata, 'home_page'):
            result['home_page'] = str(metadata.home_page) if metadata.home_page is not None else None
        if hasattr(metadata, 'author'):
            result['author'] = str(metadata.author) if metadata.author is not None else None
        if hasattr(metadata, 'author_email'):
            result['author_email'] = str(metadata.author_email) if metadata.author_email is not None else None
        if hasattr(metadata, 'license'):
            result['license'] = str(metadata.license) if metadata.license is not None else None

        # Handle lists - convert to lists of strings
        if hasattr(metadata, 'classifier'):
            result['classifier'] = [str(c) for c in metadata.classifier] if metadata.classifier else []
        if hasattr(metadata, 'requires_dist'):
            result['requires_dist'] = [str(r) for r in metadata.requires_dist] if metadata.requires_dist else []
        if hasattr(metadata, 'requires_python'):
            result['requires_python'] = str(metadata.requires_python) if metadata.requires_python is not None else None

        return result
    except Exception as e:
        raise ValueError(f"Failed to parse email metadata: {str(e)}") from e

from packaging.metadata import Metadata


def convert_metadata_to_rfc822(metadata_dict: dict[str, object]) -> str:
    """Convert metadata dictionary to RFC822 message format. metadata_dict: dictionary containing metadata fields, e.g. {'name': 'test', 'version': '1.0'} -> RFC822 formatted string."""
    try:
        metadata = Metadata(metadata_dict)
        rfc822_message = metadata.as_rfc822()
        return str(rfc822_message)
    except Exception as e:
        raise ValueError(f"Failed to convert metadata to RFC822: {str(e)}")

from typing import Any, Mapping, Dict, Union
from packaging.pylock import Pylock, PylockValidationError


def create_pylock_from_dict(data: Dict[str, Any]) -> Dict[str, Any]:
    """Create and validate a Pylock instance from a TOML dictionary. data: a dictionary representing pylock data, e.g. {'project': {'name': 'test', 'version': '1.0.0'}} -> validated Pylock object"""
    try:
        pylock_instance = Pylock.from_dict(data)
        # Convert to dictionary representation for JSON serialization
        return {
            "project": pylock_instance.project,
            "dependencies": pylock_instance.dependencies,
            "dev_dependencies": pylock_instance.dev_dependencies
        }
    except PylockValidationError as e:
        raise ValueError(f"Invalid pylock data: {str(e)}")
    except Exception as e:
        raise ValueError(f"Failed to create pylock from dictionary: {str(e)}")

