from packaging.ranges import VersionRange


def create_empty_version_range(prereleases: bool | None = None) -> dict[str, bool]:
    """Return an empty version range that accepts no versions. prereleases: whether prereleases should be considered when determining if a version is in the range. -> a dictionary representing the empty version range."""
    try:
        result = VersionRange.empty(prereleases=prereleases)
        return {"is_empty": result.is_empty}
