def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Return a version range that only accepts a single specific version. version: A PEP 440 compliant version string, e.g. '1.0' -> '{1.0}'. prereleases: Whether to include pre-release versions."""
    try:
        range_obj = VersionRange.singleton(version, prereleases=prereleases)
        return str(range_obj)
    except Exception as e:
        if "InvalidVersion" in str(type(e)):
            raise ValueError(f"not a valid PEP 440 version: {version!r}") from e
        raise ValueError(str(e)) from e

