def check_version_in_specifier_set(specifier_set: str, version: str, prereleases: bool | None = None) -> bool:
    """Check if a version is contained within a specifier set. specifier_set: A string representing the version specifier set (e.g., '>=1.0.0,!=1.0.1'), version: The version string to check against the specifier set, prereleases: Whether or not to match prereleases with this SpecifierSet. If set to None (the default), it will follow the recommendation from PEP 440."""
